import random
import string
from typing import List

# This generator targets inputs for FUZZ_PARAM_STR used by the StringBuilder_write stub.
# The stub uses strlen on the produced C string, so only bytes up to the first NUL are
# appended. We therefore generate interesting, valid NUL-terminated strings that cover
# diverse content: empty, small ASCII, long strings, whitespace-heavy, control chars
# (but avoid embedded NUL before the terminator so strlen sees full length), repeated
# patterns, numeric, punctuation, and mixed UTF-8 sequences (valid UTF-8 bytes are fine
# as ordinary bytes for C strings).
#
# Output must be a single bytes object (<=4096 bytes) to seed FUZZ_PARAM_STR.

MAX_TOTAL = 4096

ASCII_PRINTABLE = string.ascii_letters + string.digits + string.punctuation + " "
WHITESPACE = "\t\n\r \v\f"
CONTROL = bytes(range(1, 32))  # exclude NUL (0)

UTF8_SAMPLES = [
    "αβγδεζηθικλμνξοπρστυφχψω",
    "漢字かなカナ",
    "😀😃😄😁😆😅😂🤣☺️😊",
    "ąęćłńóśżź",
    "русскийтекст",
]

COMMON_WORDS = [
    "GET ", "POST ", "Content-Type: ", "User-Agent: ",
    "SELECT * FROM ", "INSERT INTO ", "../../..//",
    "--long-option=", "-short ", "key=value", "PATH=",
    "export ", "printf ", "%s %d %x %p ",
]

REPEAT_PATTERNS = [
    b"A", b"0", b" ", b"\t", b"\n", b"/", b"\\", b"%", b"-", b"_",
    b"ab", b"01", b"CRLF\r\n", b"..//", b"\r\n",
]


def _rand(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)


def _choose(r: random.Random, seq: List):
    return seq[_rand(r, 0, len(seq) - 1)]


def _gen_ascii(r: random.Random, n: int) -> bytes:
    return ("".join(r.choice(ASCII_PRINTABLE) for _ in range(n))).encode("ascii")


def _gen_whitespace(r: random.Random, n: int) -> bytes:
    return ("".join(r.choice(WHITESPACE) for _ in range(n))).encode("ascii")


def _gen_control(r: random.Random, n: int) -> bytes:
    # choose from control bytes 1..31 (avoid NUL), plus some printable
    pool = list(CONTROL) + [ord("\t"), ord("\n"), ord("\r")] + [ord(" ")]
    return bytes(r.choice(pool) for _ in range(n))


def _gen_utf8(r: random.Random, n: int) -> bytes:
    # build from chosen UTF-8 samples, repeat/truncate to size
    s = _choose(r, UTF8_SAMPLES)
    buf = (s * ((n // max(1, len(s))) + 1))[:n]
    return buf.encode("utf-8", errors="ignore")


def _gen_patterns(r: random.Random, n: int) -> bytes:
    out = bytearray()
    while len(out) < n:
        p = _choose(r, REPEAT_PATTERNS)
        rep = _rand(r, 1, max(1, (n - len(out)) // max(1, len(p))))
        out.extend(p * rep)
        # cap
        if len(out) > n:
            del out[n:]
            break
    return bytes(out)


def _gen_words(r: random.Random, n: int) -> bytes:
    out = bytearray()
    while len(out) < n:
        w = _choose(r, COMMON_WORDS).encode("utf-8")
        out.extend(w)
        if len(out) >= n:
            break
    return bytes(out[:n])


def _mix(r: random.Random, target_len: int) -> bytes:
    gens = [_gen_ascii, _gen_whitespace, _gen_control, _gen_utf8, _gen_patterns, _gen_words]
    chunks = []
    remaining = target_len
    while remaining > 0:
        g = _choose(r, gens)
        # bias toward smaller chunks to increase variety
        chunk_len = min(remaining, max(1, int(r.paretovariate(2) % max(1, remaining))))
        # ensure at least 1 byte
        if chunk_len <= 0:
            chunk_len = min(remaining, _rand(r, 1, max(1, remaining)))
        chunk = g(r, chunk_len)
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def _make_c_string(r: random.Random, target_len: int) -> bytes:
    # Ensure no embedded NUL before terminator: generate without NUL and append one.
    # We also create several structured cases to trigger interesting append lengths.
    case = _rand(r, 0, 8)
    if case == 0:
        payload = b""  # empty string
    elif case == 1:
        payload = _gen_ascii(r, target_len)
    elif case == 2:
        payload = _gen_whitespace(r, target_len)
    elif case == 3:
        payload = _gen_control(r, target_len)
    elif case == 4:
        payload = _gen_utf8(r, target_len)
    elif case == 5:
        payload = _gen_patterns(r, target_len)
    elif case == 6:
        payload = _gen_words(r, target_len)
    else:
        payload = _mix(r, target_len)

    # Strip any accidental NULs that could truncate strlen prematurely.
    payload = payload.replace(b"\x00", b"\x01")

    return payload + b"\x00"  # proper NUL termination


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose a target logical append length with a broad distribution.
    size_choice = r.random()
    if size_choice < 0.10:
        target_len = 0
    elif size_choice < 0.25:
        target_len = _rand(r, 1, 8)
    elif size_choice < 0.55:
        target_len = _rand(r, 9, 64)
    elif size_choice < 0.85:
        target_len = _rand(r, 65, 512)
    else:
        # Large but bounded to keep total <= 4096 after NUL terminator
        target_len = _rand(r, 513, 4095)

    cstr = _make_c_string(r, target_len)

    # Ensure overall bound
    if len(cstr) > MAX_TOTAL:
        cstr = cstr[:MAX_TOTAL-1] + b"\x00"

    return cstr
